$signed=$contract['status']==='signed';
$monthly=(float)($contract['monthly_fixed_amount']??0);
$commercialReady=$signed&&(!$splitRequired||$walletReady);
$signatureSteps=[
 ['label'=>'Gerado','date'=>$contract['created_at']??null],
 ['label'=>'Liberado','date'=>$contract['sent_at']??null],
